mapper.select:
SELECT FROM stat_access_daily WHERE stat_date BETWEEN #{from} AND #{to} AND user_type IS NULL AND bucket_hour IS NULL
AND site_id = #{siteId}
ORDER BY stat_date ASC

SELECT NULL AS stat_id, MAX(stat_date) AS stat_date, #{siteId} AS site_id, NULL AS site_code, user_type, NULL AS bucket_hour, SUM(pv) AS pv, SUM(uv) AS uv, SUM(unique_users) AS unique_users, ROUND(AVG(avg_response_ms)) AS avg_response_ms, 0 AS p95_response_ms, SUM(err_4xx) AS err_4xx, SUM(err_5xx) AS err_5xx, SUM(bytes_sent) AS bytes_sent, NOW() AS computed_at FROM stat_access_daily WHERE stat_date BETWEEN #{from} AND #{to} AND user_type IS NOT NULL AND bucket_hour IS NULL
AND site_id = #{siteId}
GROUP BY user_type ORDER BY pv DESC

SELECT NULL AS stat_id, MAX(stat_date) AS stat_date, #{siteId} AS site_id, NULL AS site_code, NULL AS user_type, bucket_hour, SUM(pv) AS pv, SUM(uv) AS uv, SUM(unique_users) AS unique_users, ROUND(AVG(avg_response_ms)) AS avg_response_ms, 0 AS p95_response_ms, SUM(err_4xx) AS err_4xx, SUM(err_5xx) AS err_5xx, SUM(bytes_sent) AS bytes_sent, NOW() AS computed_at FROM stat_access_daily WHERE stat_date BETWEEN #{from} AND #{to} AND user_type IS NULL AND bucket_hour IS NOT NULL
AND site_id = #{siteId}
GROUP BY bucket_hour ORDER BY bucket_hour ASC

SELECT NULL AS stat_id, MAX(stat_date) AS stat_date, site_id, MAX(site_code) AS site_code, request_uri, SUM(pv) AS pv, SUM(uv) AS uv, ROUND(AVG(avg_response_ms)) AS avg_response_ms, NOW() AS computed_at FROM stat_access_uri_daily WHERE stat_date BETWEEN #{from} AND #{to}
AND site_id = #{siteId}
GROUP BY site_id, request_uri ORDER BY pv DESC LIMIT #{limit}

SELECT v.stat_date, v.site_id, s.site_code AS site_code, v.visit_count, v.unique_count, v.pv_count FROM stat_daily_visit v LEFT JOIN gopcms_primary.tb_site s ON s.site_id = v.site_id WHERE v.stat_date BETWEEN #{from} AND #{to}
AND v.site_id = #{siteId}
ORDER BY v.stat_date ASC, v.site_id ASC

SELECT IFNULL(SUM(pv), 0) AS totalPv, IFNULL(SUM(uv), 0) AS totalUv, IFNULL(SUM(unique_users), 0) AS totalUniqueUsers, IFNULL(ROUND(AVG(avg_response_ms)),0) AS avgResponseMs, IFNULL(SUM(err_4xx), 0) AS err4xx, IFNULL(SUM(err_5xx), 0) AS err5xx, IFNULL(SUM(bytes_sent), 0) AS bytesSent FROM stat_access_daily WHERE stat_date BETWEEN #{from} AND #{to} AND user_type IS NULL AND bucket_hour IS NULL
AND site_id = #{siteId}
AND site_id IS NULL
